pub(crate) struct PgByteBackupObservation{pub status:&'static str,pub completed_at:Option<String>}
pub(crate) async fn retain_normal_pg_backup_history(serving:Option<std::sync::Arc<QualifiedPgServing>>,state:&crate::AppState)->anyhow::Result<()>{if crate::db::DatabaseEngine::from_url(state.db.connect_options().database_url.as_str()).ok()!=Some(crate::db::DatabaseEngine::Postgres){return Ok(())}let Some(path)=std::env::var_os("STORAGE_OPERATION_RECORDS_DIR")else{return Ok(())};let serving=serving.context("PG byte-backup history has no original qualified startup source")?;let proof=match serving.as_ref(){QualifiedPgServing::Transfer(s)=>PgByteSourceProof::Transfer(s),QualifiedPgServing::PgRestore(s)=>PgByteSourceProof::Restored(s)};ensure!(std::sync::Arc::ptr_eq(&serving.pool().connect_options(),&state.db.connect_options()),"PG byte-backup startup pool differs from original serving pool");let mut conn=state.db.acquire().await?;proof.connection(&mut conn).await?;let store=PgByteBackupStore::selected(Path::new(&path),proof.root(),None,&state.jwt_secret,false)?;proof.connection(&mut conn).await?;drop(conn);let pool=state.db.connect_options();ensure!(PG_NORMAL_BYTE_BACKUP_READER.set(std::sync::Arc::new(PgNormalByteBackupReader{serving,pool,store})).is_ok(),"PG byte-backup startup reader already selected");Ok(())}
pub(crate) async fn observe_normal_pg_backup_history(state:&crate::AppState)->PgByteBackupObservation{let Some(reader)=PG_NORMAL_BYTE_BACKUP_READER.get()else{return PgByteBackupObservation{status:if std::env::var_os("STORAGE_OPERATION_RECORDS_DIR").is_some(){"unavailable"}else{"unknown"},completed_at:None}};let result=tokio::time::timeout(std::time::Duration::from_secs(2),async{ensure!(std::sync::Arc::ptr_eq(&reader.pool,&state.db.connect_options())&&reader.store.key==state.jwt_secret.as_bytes()&&std::env::var_os("STORAGE_OPERATION_RECORDS_DIR").map(PathBuf::from).as_ref()==Some(&reader.store.root.absolute),"Original PG byte-backup reader pool/configuration changed");let proof=match reader.serving.as_ref(){QualifiedPgServing::Transfer(s)=>PgByteSourceProof::Transfer(s),QualifiedPgServing::PgRestore(s)=>PgByteSourceProof::Restored(s)};let mut conn=state.db.acquire().await?;proof.connection(&mut conn).await?;let original=proof.identity()?;let time=reader.store.latest(&original)?;proof.connection(&mut conn).await?;ensure!(proof.identity()?==original,"Original PG byte-backup source changed during observation");reader.store.fence()?;Ok::<_,anyhow::Error>(time)}).await;match result{Ok(Ok(Some(time)))=>PgByteBackupObservation{status:"recorded_completed",completed_at:Some(time)},Ok(Ok(None))=>PgByteBackupObservation{status:"unknown",completed_at:None},_=>PgByteBackupObservation{status:"unavailable",completed_at:None}}}

